require('./test-six-archives-index.cjs');
const fs=require('fs'),path=require('path'),M=require('../src/models'),R=require('../src/modules/report/employeeProfitSummary');
(async()=>{const r=await R.load({staffId:1,roles:['boss'],accessibleStoreIds:['*']},{startDate:'2026-10-01',endDate:'2026-10-31',reportRole:'all'});const out={sales:r.panels.sales,rows:r.rows.filter(r=>r.rule==='manager').map(r=>({name:r.employeeName,store:r.storeName,staffId:r.staffId,storeGross:r.storeGrossProfit,line:r.breakEvenLine,personal:r.salesCommission,storeCommission:r.storeCommission,total:r.performanceEstimate,status:r.status}))};const file=process.argv.includes('--after')?'after':'before';const dir=path.resolve(__dirname,'../backup/manager-threshold-20261112');fs.mkdirSync(dir,{recursive:true});fs.writeFileSync(path.join(dir,file+'.json'),JSON.stringify(out,null,2));console.log(JSON.stringify(out));})().catch(e=>{console.error(e.stack);process.exitCode=1}).finally(()=>M.sequelize.close());
